<section class="pet-public"><div class="container"><div class="pet-public-card"><div class="pet-public-top status-<?= e($pet['status']) ?>"><div class="brand brand-dark"><span class="brand-symbol">RV</span><span>RedVecinal</span></div><span class="badge"><?= e(str_replace('_',' ',$pet['status'])) ?></span></div><div class="pet-profile"><div class="pet-large-avatar"><?= e(mb_strtoupper(mb_substr($pet['name'],0,1))) ?></div><h1><?= e($pet['name']) ?></h1><p><?= e($pet['species']) ?><?= $pet['breed']?' · '.e($pet['breed']):'' ?><?= $pet['color']?' · '.e($pet['color']):'' ?></p><?php if($pet['description']):?><div class="pet-description"><?= nl2br(e($pet['description'])) ?></div><?php endif;?><?php if($pet['status']==='perdida'):?><div class="lost-alert"><strong>Esta mascota está perdida</strong><span>Vista por última vez en <?= e($pet['last_seen_address']?:$pet['commune_name']) ?>.</span></div><?php endif;?><a class="btn btn-success btn-lg w-100" href="tel:<?= e($pet['owner_phone']) ?>">Llamar a <?= e($pet['owner_name']) ?></a></div><div class="sighting-form"><h2>¿Viste a <?= e($pet['name']) ?>?</h2><p>Envía su ubicación aproximada al responsable.</p><form method="post" action="<?= url('mascota/qr/'.$pet['qr_token'].'/avistamiento') ?>"><?= csrf_field() ?><div class="row g-3"><div class="col-md-6"><input class="form-control" name="reporter_name" placeholder="Tu nombre"></div><div class="col-md-6"><input class="form-control" name="reporter_phone" placeholder="Tu teléfono"></div><div class="col-12"><input class="form-control" name="address" placeholder="Lugar donde la viste"></div><div class="col-12"><textarea class="form-control" name="notes" required placeholder="Cuéntanos detalles del avistamiento"></textarea></div><input type="hidden" name="latitude"><input type="hidden" name="longitude"><div class="col-md-6"><button type="button" class="btn btn-outline-primary w-100" data-geolocate>◎ Usar ubicación</button></div><div class="col-md-6"><button class="btn btn-primary w-100">Enviar aviso</button></div></div></form></div></div></div></section>

